// Parse the LLM JSON response and merge with the original email fields.
const email = $('Gmail Trigger').item.json;
let parsed = {};
try {
  const raw = $input.item.json;
  const content = raw.choices && raw.choices[0] && raw.choices[0].message
    ? raw.choices[0].message.content
    : (raw.content || '{}');
  parsed = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  parsed = { label: 'other', request_type: 'none', confidence: 0, reason: 'parse_error', needs_human: true };
}

const label = ['urgent', 'lead', 'invoice', 'newsletter', 'other'].includes(parsed.label)
  ? parsed.label
  : 'other';

return {
  json: {
    id: email.id,
    threadId: email.threadId,
    from: email.from,
    subject: email.subject,
    snippet: email.snippet || '',
    label,
    request_type: parsed.request_type || 'none',
    confidence: Number(parsed.confidence) || 0,
    reason: parsed.reason || '',
    needs_human: parsed.needs_human !== false,
    triaged_at: new Date().toISOString()
  }
};

