// Pull the drafted reply text out of the LLM response.
const meta = $('Parse Classification').item.json;
const raw = $input.item.json;
let body = '';
try {
  body = raw.choices && raw.choices[0] && raw.choices[0].message
    ? raw.choices[0].message.content
    : (raw.content || '');
} catch (e) {
  body = '';
}
return {
  json: {
    ...meta,
    draft_body: (body || '').toString().trim()
  }
};

