// Collect every triaged email into one digest string.
// Runs once per execution over all incoming items.
const rows = items.map(i => i.json);
const byLabel = {};
for (const r of rows) {
  byLabel[r.label] = byLabel[r.label] || [];
  byLabel[r.label].push(r);
}
const order = ['urgent', 'lead', 'invoice', 'newsletter', 'other'];
let digest = `DAILY INBOX DIGEST - ${new Date().toISOString().slice(0,10)}\n`;
digest += `Total triaged: ${rows.length}\n`;
digest += `Drafts created: ${rows.filter(r => r.draft_body).length}\n\n`;
for (const label of order) {
  const group = byLabel[label] || [];
  if (!group.length) continue;
  digest += `== ${label.toUpperCase()} (${group.length}) ==\n`;
  for (const r of group) {
    const flag = r.needs_human ? ' [NEEDS HUMAN]' : '';
    const drafted = r.draft_body ? ' [DRAFT READY]' : '';
    digest += `- ${r.from} | ${r.subject}${drafted}${flag}\n  ${r.reason}\n`;
  }
  digest += `\n`;
}
return [{ json: { digest, count: rows.length, generated_at: new Date().toISOString() } }];
